mapper.sql:
rr.display_rank=1
and (rr.question_code ilike concat('%',#{query.keyword},'%') or rr.stem ilike concat('%',#{query.keyword},'%'))
and rr.question_type=#{query.questionType}
and rr.difficulty=#{query.difficulty}
and rr.status=#{query.status}
and exists (select 1 from cm_exam_subject es where es.id=rr.exam_subject_id and es.certification_id=#{certificationId})
and rr.exam_subject_id=#{subjectId}

  and exists (select 1 from cm_question_knowledge qk join cm_knowledge_point kp on kp.id=qk.knowledge_point_id
               where qk.question_revision_id=rr.id and kp.del_flag='0' and kp.syllabus_version_id=#{syllabusId})


  and exists (
    with recursive descendants(id) as (
      select #{knowledgeId}::bigint

      union all select child.id from cm_knowledge_point child join descendants d on child.parent_id=d.id where child.del_flag='0'

    )
    select 1 from cm_question_knowledge qk join descendants d on d.id=qk.knowledge_point_id
     where qk.question_revision_id=rr.id
  )
